// === Tab: Sketch ===
// By Roni Kaufman
// inspired by https://www.instagram.com/p/B6Rtb0Tnwc3/?igshid=d5co693jh5wy

let nCircles = 50;
let nWaves = 2;
let inter = 10;

function setup() {
  createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 100);
  noFill();
}

function draw() {
  background(8);

  let size = inter;
  for (let i = 1; i <= nCircles; i++) {
    strokeWeight(Math.max(0.1, Math.abs(inter/9)));
		stroke(2);
    circle(width/2, height/2, size);

    strokeWeight(Math.max(0.1, Math.abs(inter/3)));
    let delta = pow(i, 2)/1600;
		//let delta = pow(i, 3)/80000;

    let theta = cos(frameCount/25 - i/3)/4;
    for (let j = 0; j < nWaves; j++) {
			stroke(abs(i/4 + j*50 - frameCount/10 - 50)%100, 100, 100);
      arc(width/2, height/2, size, size, 
          theta - delta, theta + delta);
      theta += TWO_PI / nWaves;
    }

    size += inter;

  }
}
